import {escapeHTML as e,imageURL} from './store.js';
import {navIcon} from './icons.js';
export function studioOverview(w){
 const n=w.narrative||{},events=[...(n.events||[])].sort((a,b)=>a.year-b.year||a.month-b.month||a.day-b.day).slice(0,3);
 return `<section class="studio-summary"><div class="section-heading"><div><span class="eyebrow">SEU MUNDO EM MOVIMENTO</span><h2>O universo em números</h2></div></div><div class="studio-metrics">${[['notes','Documentos',w.notes.length+w.folderNotes.length],['characters','Personagens',w.characters.length],['maps','Mapas',w.maps.length],['connections','Conexões',n.relations?.length||0]].map(([key,label,value])=>`<button data-dashboard-view="${key}">${navIcon(key)}<strong>${value}</strong><span>${label}</span></button>`).join('')}</div></section><section class="studio-agenda atelier-panel"><div class="section-heading"><div><span class="eyebrow">UM PASSO DE CADA VEZ</span><h2>Próximos passos</h2></div></div><form id="studioTaskForm"><input name="task" placeholder="O que você quer desenvolver?" maxlength="180" required aria-label="Novo próximo passo"><button class="button" type="submit" aria-label="Adicionar próximo passo">＋</button></form><div id="studioTasks"></div></section><section class="studio-chronicle atelier-panel"><div class="section-heading"><div><span class="eyebrow">NO TEMPO DO SEU MUNDO</span><h2>Acontecimentos em destaque</h2></div><button class="text-link" data-dashboard-view="timeline">Ver cronologia ↗</button></div>${events.map(ev=>`<button class="studio-event" data-dashboard-view="timeline"><span>${String(ev.day).padStart(2,'0')}<small>${e(n.calendar?.months?.[ev.month]?.name||'Mês')}</small></span><div><strong>${e(ev.title)}</strong><small>Ano ${e(ev.year)} · ${e(n.calendar?.era||'')}</small></div>${navIcon('arrowUpRight')}</button>`).join('')||'<p class="help">Registre o primeiro acontecimento na linha do tempo para vê-lo aqui.</p>'}</section>`;
}
export function mountStudioTasks(main,w,save,opts){
 const form=main.querySelector('#studioTaskForm'),list=main.querySelector('#studioTasks');if(!form)return;
 if(!Array.isArray(w.overview.tasks))w.overview.tasks=[];
 const draw=()=>{list.innerHTML=w.overview.tasks.map((t,i)=>`<div class="studio-task"><label><input type="checkbox" data-task="${i}" ${t.done?'checked':''}><span>${e(t.text)}</span></label><button type="button" data-remove-task="${i}" aria-label="Remover ${e(t.text)}">×</button></div>`).join('')||'<p class="help">Uma pequena lista para dar direção à sua próxima sessão.</p>';};
 form.addEventListener('submit',ev=>{ev.preventDefault();const text=form.elements.task.value.trim();if(!text)return;w.overview.tasks.push({text,done:false});form.reset();save();draw();},opts);
 list.addEventListener('change',ev=>{if(ev.target.dataset.task===undefined)return;w.overview.tasks[+ev.target.dataset.task].done=ev.target.checked;save();},opts);
 list.addEventListener('click',ev=>{const b=ev.target.closest('[data-remove-task]');if(!b)return;w.overview.tasks.splice(+b.dataset.removeTask,1);save();draw();},opts);draw();
}
export function mountCardTilt(container){
 if(!matchMedia('(hover:hover) and (prefers-reduced-motion:no-preference)').matches)return;
 container.querySelectorAll('[data-kind="characters"]').forEach(card=>{
  let frame=0;card.onpointermove=ev=>{if(ev.pointerType==='touch')return;const r=card.getBoundingClientRect(),x=(ev.clientX-r.left)/r.width,y=(ev.clientY-r.top)/r.height;cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{card.style.setProperty('--tilt-x',`${(0.5-y)*9}deg`);card.style.setProperty('--tilt-y',`${(x-.5)*9}deg`);card.style.setProperty('--glow-x',`${x*100}%`);card.style.setProperty('--glow-y',`${y*100}%`);});};
  card.onpointerleave=()=>{cancelAnimationFrame(frame);card.style.setProperty('--tilt-x','0deg');card.style.setProperty('--tilt-y','0deg');};
 });
}
export function characterSheet(item){return `<article class="character-sheet"><header class="character-sheet-hero">${imageURL(item.image)?`<img src="${imageURL(item.image)}" alt="${e(item.name)}">`:`<div class="character-monogram">${e(item.name.slice(0,1))}</div>`}<div><span class="eyebrow">${e(item.role||'PERSONAGEM')}</span><h2>${e(item.name)}</h2><div class="character-facts"><span>${e(item.species||'Espécie não definida')}</span><span>${e(item.age||'Idade não definida')}</span></div></div></header><div class="character-sheet-sections">${[['Descrição e personalidade',item.description],['Motivações e desejos',item.motivation],['Conflitos e segredos',item.conflict]].map(([label,text])=>`<section><h3>${label}</h3><p>${e(text||'Ainda há uma história para descobrir.')}</p></section>`).join('')}</div><button type="button" class="button" id="editCharacterSheet">Editar personagem</button></article>`;}
